#!/usr/bin/env bash
# =============================================================================
# check-requirements-lock.sh — requirements.lock is complete and agrees with
# requirements.txt (offline; no network).
#
# requirements.txt holds the DIRECT pins; requirements.lock (generated by
# tools/gen-requirements-lock.py) is what every installer uses with
# `pip --require-hashes`. This gate refuses a lock that has drifted from the
# pins, an entry that is not an exact == pin, an entry with no hash, a hash
# that is not 64 hex characters, or a duplicate package. It checks STRUCTURE
# and AGREEMENT; whether the hashes match PyPI is proven by installing from it
# (pip refuses a mismatch) and by `gen-requirements-lock.py --check`.
#
#   bash tools/check-requirements-lock.sh [--root DIR]
#
# Exit: 0 consistent · 1 not · 3 could not run.
#
# Copyright (c) 2025-2026 James Rodman. All Rights Reserved.
# =============================================================================
set -uo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[[ "${1:-}" == "--root" ]] && ROOT="${2:-}"
PY="${PYTHON:-python3}"
command -v "$PY" >/dev/null 2>&1 || PY=python
command -v "$PY" >/dev/null 2>&1 || { echo "check-requirements-lock: no python found" >&2; exit 3; }

"$PY" - "$(cygpath -m "$ROOT" 2>/dev/null || printf '%s' "$ROOT")" <<'PYCHK'
import os, re, sys
root = sys.argv[1]
def norm(n): return re.sub(r"[-_.]+", "-", n).lower()
req = os.path.join(root, "requirements.txt"); lock = os.path.join(root, "requirements.lock")
if not os.path.isfile(lock):
    print("FAIL: requirements.lock is missing — the installers use it with --require-hashes"); sys.exit(1)
pins = {}
for line in open(req, encoding="utf-8"):
    line = line.split("#")[0].strip()
    if "==" in line:
        n, v = line.split("==", 1); pins[norm(n)] = v.strip()
if not pins:
    print("FAIL: no == pins in requirements.txt"); sys.exit(1)
text = open(lock, encoding="utf-8").read().replace("\r\n", "\n").replace("\\\n", " ")
entries, fail = {}, 0
for line in text.splitlines():
    line = line.split("#", 1)[0].strip() if not line.lstrip().startswith("--hash") else line.strip()
    if not line:
        continue
    m = re.match(r"^([A-Za-z0-9._-]+)==([^\s]+)((?:\s+--hash=sha256:\S+)*)\s*$", line)
    if not m:
        print("FAIL: requirements.lock: not an exact pin with hashes: %s" % line[:80]); fail += 1; continue
    name, ver, hs = norm(m.group(1)), m.group(2), re.findall(r"--hash=sha256:(\S+)", m.group(3))
    if name in entries:
        print("FAIL: %s appears twice in requirements.lock" % name); fail += 1
    if not hs:
        print("FAIL: %s==%s has no --hash" % (name, ver)); fail += 1
    bad = [h for h in hs if not re.fullmatch(r"[0-9a-f]{64}", h)]
    if bad:
        print("FAIL: %s has a malformed hash: %s" % (name, bad[0][:20])); fail += 1
    entries[name] = ver
for n, v in sorted(pins.items()):
    if n not in entries:
        print("FAIL: requirements.txt pins %s==%s but requirements.lock does not carry it" % (n, v)); fail += 1
    elif entries[n] != v:
        print("FAIL: %s is %s in requirements.txt but %s in requirements.lock — regenerate the lock"
              % (n, v, entries[n])); fail += 1
if fail:
    print("check-requirements-lock: %d problem(s)." % fail); sys.exit(1)
print("check-requirements-lock: %d packages locked (%d direct pins agree), every one hash-pinned."
      % (len(entries), len(pins)))
PYCHK
rc=$?
[[ $rc -eq 0 ]] || exit "$rc"

# ── completeness (round 8, gatekeeper) ───────────────────────────────────────
# The checks above prove STRUCTURE and AGREEMENT with the direct pins. They
# cannot see a transitive package the lock simply lacks. That needs the
# resolved set, which needs PyPI: resolved with the lock's own generator
# (--check-set compares name==version, not the hash lists). Offline, say so —
# never pass silently.
GEN="${ROOT}/tools/gen-requirements-lock.py"
[[ -f "$GEN" ]] || GEN="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/gen-requirements-lock.py"
if ! command -v curl >/dev/null 2>&1 || ! curl -sfI --max-time 8 -o /dev/null https://pypi.org/simple/pip/; then
    echo "check-requirements-lock: lock completeness NOT verified (offline) — structure and agreement only."
    exit 0
fi
out="$("$PY" "$GEN" --check-set --root "$(cygpath -m "$ROOT" 2>/dev/null || printf '%s' "$ROOT")" 2>&1)"
crc=$?
out="$(grep -v '^\[notice\]' <<<"$out" | sed '/^$/d')"
case "$crc" in
    0) echo "check-requirements-lock: ${out##*$'\n'}" ;;
    1) printf '%s\n' "$out"; echo "check-requirements-lock: the lock does not cover the resolved set — regenerate it."; exit 1 ;;
    *) printf '%s\n' "$out"; echo "check-requirements-lock: lock completeness NOT verified (resolution failed, exit ${crc}) — refusing to pass."; exit 3 ;;
esac
